    "Title": "Beim Schiefen auf die Torwand und Pony-Reiten erfreut",
    "Date": "2029-02-29",
    "Summary": "Reileifzener Waldfest wurde ein voller Erfolg. Dank dem Verkehrsverein der Gemeinde Reileifzen. Bei strahlendem Sonnenschein feierte die Bevölkerung von Reileifzen mit ihren Gästen kürzlich das Reileifzener Waldfest. Aufgrund der Werbung und des Programms, das geboten wurde, ist das Fest auch von vielen Auswärtigen besucht worden. Dank der tatkräftigen Hilfe der meisten Verkehrsvereins-Mitglieder wurde die Ausgestaltung des Platzes termingerecht fertiggestellt. Der gut ausgeschmückte Festplatz wies den Besuchern schon von weitem den Wes.",
