    "Summary": "Auf der KreisstraBe 35 zwischen Reileif- zen und Riuhle sind einige Veraénderungen nach Fertigstel- lung des. Streckenabschnitts Rihle-Délme vorgenommen wor- den. So ist beispielsweise die Strecke Ruhle-Délme nicht mehr fir *den. Schwerlastverkehr Uber 2,8 Tonnen gesperrt. Eine entsprechende Ver- kehrsbeschrankung fir Fahrzeuge uber 2,8 Tonnen wurde jedoch fur den Bereich vom Ortsausgang Rei- leifzen bis Délme und umgekehrt verhangt. Grund dieser Beschrankung fir den Schwerlastverkehr sind zum einen die enge Fahrbahnfthrung und zum anderen die in den Rand- bereich hineinragenden Felswan- de. Land- und forstwirtschaftlicher Verkehr ist hiervon ausgenommen.",
