    "Date": "1990-01-01",
    "Summary": "Der Vorstand des Reichsbundes der Kriegs- und Wehrdienstopfer, Behinderten, Sozialrentner und Hinterbliebenen Ortsgruppe Bevern-Lobach-Reileifzen hatte seine Mitglieder zur Jahreshauptversammlung eingeladen. Vorsitzender Helmut Meese konnte ein Drittel seiner Mitglieder begrüßen.",
