    "Title": "Kiesabbau bei Reileifzen soll iiber de J ahrhundertwende hinaus fortgesetzt werden",
    "Date": "1995-10-12",
    "Summary": "Die Kiesgrube bei Reileifzen soll weiterhin über die Jahrhundertwende hinaus ausgebeutet werden. Naturschützer sind besorgt, da das freigelegte Grundwasser von Luftschadstoffen bedroht ist und die Fließrichtung der Grundwasserströme beeinflussen kann. Die Kiesgrube dient als Ersatzlebensraum für verschiedene Tier- und Pflanzenarten, darunter Amphibien und Libellen.",
