    "Title": "Die Uberraschung in der ici Sitzung des Rates der Samtgemeinde Bevern",
    "Date": "1995-12-08",
    "Summary": "In der Sitzung des Rates der Samtgemeinde Bevern am letzten Mittwoch sorgte der Abgeordnete Friedrich Hoffmeister aus Reileifzen für die Uberraschung. Er verließ die SPD-Fraktion, der er seit 1981 angehört und kündigte für den nächsten Tag eine entsprechende Erklärung an, die allerdings am gesirigen Donnerstag noch nicht vorlag.",
