    "Title": "Fachausschuf in Reileifzen-Délme",
    "Date": "1996-06-05",
    "Summary": "Der Sport- und Jugendausschuss des Rates der Fleckengemeinde Bevern trifft sich am 5. Juni um 16 Uhr im Dortgemeinschaftshaus in Reileifzen. Es sollen Flächen besichtigt werden, die möglicherweise für Spielplätze in Reileifzen und Délme in Frage kommen. Danach wird die Fachausschusssitzung im Dorfgemeinschaftshaus in Délme fortgesetzt. Es wird über die Ausstattung der geplanten Spielplätze beraten.",
