    "Title": "tiberlebte Unfall nicht Kutschpferd",
    "Date": "1998-04-21",
    "Summary": "Eines der beiden Kutschpferde, die am Sonntag nachmittag durchgegangen waren und damit einen Unfall verursachten, ist gestern verendet. Der tragische Unfall, bei dem der Kutscher schwerste Kopfverletzungen erlitt, hatte sich auf der Kreisstrafe 35 zwischen Délme und Reileifzen ereignet (der TAH berichtete). Plétzlich hatten die erprobten Kutschpferde Natascha und Nadine gescheut und waren auf ein Auto gesprungen. Dabei hatte sich die achuahrigé Stute Nadine verletzt.",
