    "Title": "Karl Winter schreibt die Geschichte neu",
    "Date": "1900-01-01",
    "Summary": "Uber mehr als 20 Jahre hat Karl Winter, Eigentumer der Brille im Weserbogen bei Reileifzen, bei der Garten- und landwirtschaftlichen Arbeit Keramikscherben, behauene Steingerate und Lehmstucke gesammelt, an vielen Fundstellen auch mal nachgegraben. Was er in mehr als einem Dutzend Obst- und Gemisekisten in der Garage hortete, ist fur den Kreisarchaologen Christian Leiber aussagekraftiges Fundmaterial. Es gibt neue Auskunft Uber die Siedilungs- und Kulturge-schichte rund um Reileifzen. Und die ist wohl alter, als bislang angenommen.",
