    "Summary": "Riihle (r). Der Naturschutz- bund NABU, Kreisgruppe Holzminden, ladt fiir Sonntag, 20. Juni, zu einer Wanderung durch die Mittelwalder des Hangbergs in der Rihler Schweiz ein. Im Rahmen der Wanderung werden Geologie, Pflanzenwelt, Landnutzung und Waldbewirtschaftung unter Na- turschutzaspekten erldutert. Treffpunkt ist um 9.30 Uhr die PaShohe der L 580 Golmbach — Riihle (Rithler Schweiz).",
