    "Date": "2002-12-12",
    "Summary": "Uber Jahrzehnte hat Reileifzen auf diesen Moment gewartet: Jetzt bekommt der Ort eine neue Trinkwasserleitung, wird Uber Litgenade endlich an die ,,Wasserversorgung Forstbachtal” angeschlossen. Trotz Bodenfrost wurden die Arbeiten mit einem offiziellen Spatenstich in Angriff genommen. Die kalten Temperaturen sollen die Arbeiten aber nicht behindern, Ende Februar soll bereits das Wasser durch die neuen Leitungen sprudeln.",
