    "Title": "Neue Trinkwasserleitung",
    "Date": "1900-01-01",
    "Summary": "Seit Jahrzehnten schon haben die Bewohner in Reileifzen so ihre Probleme mit dem Trinkwasser. Das Wasser stammt aus Oberflachenquellen der umliegenden Berge, haufig sind Keime im Wasser, es muss Chlor zugesetzt werden, und die Druckverhaltnisse sind in den höheren Lagen des Ortes auch nicht ausreichend. Das alles wird jetzt besser, verspricht die Samtgemeinde Bevern, und schreitet zur Tat. Jetzt wird eine neue Trinkwasserleitung von Litgenade nach Reileifzen gelegt.",
