    "Title": "Arbeitseinsatz in Reileifzen",
    "Date": "2004-06-12",
    "Summary": "Am Sonnabend, 12. Juni, um 10 Uhr beginnt ein Arbeitseinsatz des Heimat- und Verkehrsvereins._Reileifzen. Treffpunkt ist am Geritehaus des Vereins. Schwerpunkte sind Pflegearbeiten in der Twete und am Leinpfadweg an der Weser.",
