    "Summary": "Gestern rollten die letzten Miillfahrzeuge auf dem Kapenberg an / 2006 kommt der millionenschwere Kreis Holzminden (bs). Methan - es stinkt penetrant nach Methan. ,Man gewohnt sich dran”, zuckt Martin Bohner, Chef der Abfallwirtschaft des Landkreises Holzminden, mit den Schultern. Gewohnt haben sich die Holzmindener auch an ihre Miulldeponie. 26 Jahre lang wurde auf dem Kapenberg abgeladen, was iberfliissig war. Jetzt ist der Kapenberg dicht. Gestern rollten die letzten Millfahrzeuge in den ehemaligen Sandsteinbruch, der in zweieinhalb Jahrzehnten nicht nur verfillt wurde, sondern zu einem neuen Berg erwachsen ist.",
