    "Summary": "Riihler Schweiz (bs/saw). Fir Landrat Walter Waske ist es eine Premiere. Vorsichtig setzt er Denise Melching die Krone aufs hiibsch frisierte Haupt. Damit. wird aus der jungen Rihlerin die Kirschbliitenkéni- gin Denise |. Ihre erste Amts- handlung: Gemeinsam mit dem Schirmherrn greift sie zum Spaten und pflanzt einen Kirschbaum. Die Krénung fin- det in Golmbach statt, einem der drei Orte in der Rihler Schweiz, die am_ gestrigen Sonntag erneut zum Kirschblii- tenfest einladen. Nach einem verhaltenen Start am spaten Vormittag erweist sich die Ruhler Schweiz am Nachmittag dann als Publikumsmagnet. In Golmbach, Reileifzen und Riih- le werden weit mehr als 5.000 Besucher gezahlit.",
