    "Title": "Japaner entdecken Reileifzen",
    "Date": "2008-04-24",
    "Summary": "Sie besichtigen den Reichstag in Berlin und den Kélner Dom, sind zu Gast im Spielcasino Baden-Baden und in Reileifzen. Am Donnerstag, 24. April, besuchen 29 Japaner und der ehemalige japanischen Botschafter Keizo Kimura das Weserdérfchen Reileifzen. Uber einen Flyer und das Internet sind die Besucher aus dem Land der aufgehenden Sonne auf das Kirschbliitenfest und Reileifzen aufmerksam gewor- den. Fiir die Japaner ist die Kirschbliite: das Frithlingssym- bol. Grund genug fiir’die Grup- pe der Deutsch-Japanischen Ge- sellschaft, bei einer Reise durch Deutschland einen Abstecher nach Reileifzen einzuplanen.",
