    "Title": "Aussichtsturm mit herrlicher Perspektive",
    "Date": "2010-06-01",
    "Summary": "Wo sich einst die Bagger in den Boden gruben, jahrelang Kies abgebaut wurde, jagen heute Fischadler, tanzen Libellen, qua- ken Wasserfriésche, lassen sich der Eisvogel blicken und zahlreiche Wasservégel beobachten. Aus der 50 Jahre alten Kiesabbaustatte in der Weserschleife zwischen Heid- brink und Reileifzen ist das wert- volle Naturschutzgebiet ,,In den Eichen“ geworden. Jetzt lassen sich Vogelwelt und Natur an die- sem herrlichen Fleck noch besser studieren. Das Niedersachsische Forstamt Neuhaus hat zwischen den beiden Kiesseen, ganz in der Nahe der KreisstraBe 25, einen Aussichtsturm errichten lassen. Rund 20-000 Euro hat die Forst- verwaltung in den Aussichtsturm investiert, der fast baugleich mit dem Aussichtsturm im Mecklen- bruch bei Silberborn ist. Der Platz fiir den iiberdachten Ausguck an der Kiesgrube bei Reileifzen ist mit Bedacht gewahlt. Die gesamte “Palette an Wasservogeln lasst sich von hier aus beobachten, der Blick reicht bis in die Riihler Schweiz. Eine Infotafel iiber den ,,Lebens- raum Kiesgrube“ und das Natur- schutzgebiet ,,In den Eichen“ will die Untere NaturschutzbehGrde im Herbst installieren. Sie soll Vogel- und Naturbeobachtern auf dem neuen Aussichtsturm tiber die Ent- stehung des Naturschutzgebietes, Lebensriume und Artengemein- schaften informieren. Die alte Vogelbeobachtungshiitte 300 Meter weiter bleibt stehen und kann weiterhin genutzt werden. Text und Fotos: Thomas Specht",
    "Document": "./docs/Xerox Scan_17102023131334.PDF",
    "Thumbnail": "./thumbs/Xerox Scan_17102023131334_thumb.jpg"
