    "Title": "Archaologen finden Siedlungsspuren in der Weseraue",
    "Date": "2010-07-30",
    "Summary": "Nur wenige Meter fehiten, dann waren die archaologischen Spuren einer vorrémischen Siedlung zwischen Polle (Heidbrink) und Reileifzen womédglich von Baggerschau- feln zerstért und als Teil des Abdeckungsmaterials auf der Mulldeponie am Kapenberg gelandet. Doch das Team um Kreisarchaologe Dr. Christian Leiber war rechtzeitig zur Stelle. Bereits am ersten Gra- bungstag sammelten sie Hunderte kleiner Keramikscher- ben.",
