    "Title": "Radweg ist seit Montag gesperrt, doch viele Touristen umfahren die Absperrungen",
    "Date": "1900-01-01",
    "Summary": "Mit einer Woche Verspätung haben gestern die Bodenaushubarbeiten in der Weseraue bei Reileifzen und der Transport zum Kapenberg begonnen. Ab 7 Uhr rollten die ersten drei Lastwagen von der Renaturierungsfliche zwischen Heidbrink und Reileifzen bis zur Deponie, die mit 30.000 Kubikmeter Auelehmboden abgedeckt wird. Ab heute sind auf der fünf Kilometer langen Strecke bis zum Deponiegipfel täglich fünf Kipper im Dist dchoialaces unterwegs. So geht das bis in die frühen Abendstunden und bis Ende September. Während der Bauphase bleibt der Weserradweg zwischen Domine Heidbri und Reileifzen gesperrt. Doch an die Verbotsschilder halten sich längst nicht alle Radtouristen. Hunderte sind es täglich, die die Absperrungen einfach umfahren.",
