    "Date": "2011-05-10",
    "Summary": "Kreis Holzminden (r). Auf Einladung des Veranstalters des internationalen Reitsportturnieres ,Horses & Dreams meets Germany” reisten 23 ,gekrénte Haupter” der Arbeitsgemeinschaft Deutsche K6éniginnen bei strahlendem Sonnenschein nach Hagen im Teutoburger Wald. Unter ihnen auch die Kirschbliitenkénigin Nadine aus der Ruhler Schweiz. Nach einer personlichen BegriBung mit einem Glas Sekt wurden die K6niginnen durch das Gelande gefuhrt. Ihnen-bot sich ein auBergewohnlich schénes Bild von Pferden, Ausstellern, Attraktionen und Sehenswirdigkeiten. Ein Héhepunkt des Tages war die Versteigerung einer lebensgroBen Pferdeskulptur zugunsten der Aktion ,,Ein Herz fiir Kinder” und zwei handgearbeite- ter Balle aus Mull, mit denen Kinder aus ‘Afrika FuBball spielen — vom Versteigerungserlés sollen echte FuBballe fir Kinder in Afrika gekauft werden. AnschlieBend wurden Nadine und ihre Kolleginnen vom Niedersachsischen Ministerprasidenten David McAllister (rechts), der Arbeitsministerin Ursula von der Leyen und dem mehrmaligen deutschen Springmeister Paul Schockemohle begriBt, die auch bei der Versteigerung mitgewirkt hatten. Foto: TAH",
