    "Title": "Besuch aus dem Land der Kirschbliite",
    "Date": "2013-04-18",
    "Summary": "Die Reileifzer®;zum: Kirschblitenfest am Sonntag, 21.. April, begrüßen zahlreiche japanische Gäste, darunter Botschafter, Konsul, Prinzessin und Freunde aus der Partnerstadt Tochigi. Besonders erwähnenswert ist die Zusage des Botschafters Takeshi Nakane und seiner Ehefrau, die den hohen Stellenwert von Reileifzen in Japan zeigt. Auch Kirschbliitenprinzessin Takako Konishi wird erwartet, die bereits im Dezember beim Modellprojekt LandZukunft dabei war. Das Festprogramm beinhaltet auch Auftritte einer japanischen Sopranistin und des Stahler Blasorchesters.",
