    "Summary": "Lisa wird zur neuen Kirschblütenkönigin gekrönt. Golmbach und Reileifzen empfangen japanische Gäste. Die Krönung der neuen Kirschblütenkönigin auf dem Golmbacher Dorfplatz wird zu einer rundum gelungenen Zeremonie. Die bisherige Königin Marina I. hat viel Spaß in ihrem Amtsjahr gehabt. Lisa Meierkord aus Golmbach wird zur neuen Kirschblütenkönigin gekrönt und repräsentiert die Rihler Schweiz. Das Kirschblütenfest in Golmbach und Reileifzen ist gut besucht. Hochrangige Gäste aus Japan werden empfangen. Die Kirschblüte hat eine besondere Bedeutung für die Japaner und die Reileifzer. Es gibt zahlreiche Veranstaltungen und Attraktionen beim Kirschblütenfest in Reileifzen.",
