    "Summary": "Mit ihren putzigen Strohhüten sehen sie aus, als könnten sie kein Wasserchen trüben. Doch die Besucher des Oktoberfestes im japanischen Tochigi wissen: Die zwölf Kerle aus Deutschland sind echte Stimmungskanonen! Als Delegation des Heimat- und Kulturvereins Reileifzen reisten sie dem Allersheimer Bier zu diesem großen Event in der 144.000-Einwohner-Stadt hinterher - und durften sich als wahre Stargäste fühlen. Spätestens nach ihrem Bühnen-Auftritt mit dem Niedersachsen-Lied wollte jeder mit der Boygroup from Germany auf Tuchfühlung gehen. Dass die Zwölf noch etwas anderes als das Festzelt gesehen haben, beweisen Fotos wie dieses: Auf dem Programm standen auch Ausflüge in die Umgebung, und nach dem Oktoberfest folgten noch einige Tage in Tokio.",
