    "Summary": "Nachdem die SchieRgemeinschaft Holzminden ihr traditionelles Adlerschießen mit dem SV Weiß-Rot Stadtoldendorf durchgeführt hatte, nahm sie mit neun Teilnehmern an den in Heinrichshagen ausgetragenen Kreismeisterschaften teil. Folgende Teilnehmer der Schießgemeinschaft konnten sich mit einem Kreismeistertitel schmücken: Jugendklasse: Kim Kuznik als zweifache Kreismeisterin im Dreistellungskampf sowie Luftgewehr freihand, Schützen Klasse Damen: Sonja Kuznik Luftgewehr Auflage, Platz eins; Schützenklasse Mannschaft Damen: Sonja Kuznik, Birgit Richter, Bianca Klinker, Luftgewehr Auflage, Platz eins; Schützenklasse Herren: Rolf Kuznik, Luftgewehr Auflage, Platz drei. Am Sonnabend, 1. April, findet das Kleinkaliber-Vereinsmeisterschießen in Stadtoldendorf auf dem Schießstand Rot-Weiß statt.",
