    "Title": "Japanische Beamtin sucht ,.Biirgerbeteiligung*",
    "Date": "2008-12-19",
    "Summary": "Tomomi Sakamoto, eine Beamtin aus Utsunomiya, Japan, besucht die Samtgemeinde Bevern, um die Formen der Bürgerbeteiligung in Deutschland zu erforschen. Sie verbringt zwei Tage dort, spricht mit dem Rathaus-Team, nimmt an einer Ausschusssitzung teil und trifft sich mit dem Sprecher der Bürgerinitiative ,,Pro Holzminden“. Sakamoto hat ein Jahr in Göttingen studiert und spricht gut Deutsch. Sie vergleicht das japanische Kommunalwesen mit dem deutschen und besucht auch die Stadtverwaltung in Lemgo. Reileifzen wurde als Ausgangspunkt für ihre Forschungen gewählt, aufgrund der Kontakte zwischen Reileifzen und dem Verband Deutsch-Japanischer Gesellschaften. Sakamoto interessiert sich für die Beteiligung der Bürger an Entscheidungsprozessen in ihrer Gemeinde und erlebt ein Beispiel dafür in einer Sitzung des Sport- und Jugendausschusses. Sie führt auch ein intensives Gespräch mit Harald Stege, dem Sprecher der Bürgerinitiative ,,Pro Holzminden“. Sakamoto verbringt ihre Zeit bei Familie Kriegel in Reileifzen und wird sicherlich von ihrer Erfahrung in Reileifzen und der Umgebung schwärmen.",
