    "Title": "Auch in diesem Jahr kein Kirschblüten-Fest",
    "Date": "1900-01-01",
    "Summary": "Ein solches Bild wie 2019 wird es in diesem Jahr nicht geben. Der Vorstand des Heimat- und Verkehrsvereins Reileifzen hat sich dazu entschlossen, das für den 18. April geplante Kirschblütenfest abzusagen. In Absprache mit dem Heimat- und Verkehrsverein Ruhle besteht Einigkeit, dass aufgrund der aktuellen Coronapandemie das Kirschblütenfest in diesem Jahr in Reileifzen und Ruhle nicht stattfinden kann. Wie schon im vergangenen Jahr wird es 2021 kein Kirschblütenfest geben. Beide Vereine hoffen darauf, im Jahr 2022 wieder das traditionelle Kirschblütenfest ausrichten zu können.",
