    "Title": "Wer will mit ans Steinhuder Meer?",
    "Date": "1900-01-01",
    "Summary": "Am 22. Juni geht der Seniorentreff Stadtoldendorf auf Fahrt ans Steinhuder Meer. Um 9 Uhr startet der Bus der Firma Monkemeier am Teichtorplatz. Nach der Ankunft in Steinhude steht der Besuch einer Aalraucherei auf dem Programm. Um dem Gaumen auch etwas zu bieten, können alle Leckereien im Anschluss genossen werden. Nach zwei Stunden Freizeit, die zum Wandern am Meer oder zum Sonne tanken genutzt werden können, besteigen die Teilnehmer das Schiff zu einer Rundfahrt bei Kaffee und Kuchen. Zurück auf festem Boden, ist für 16.40 Uhr die Heimfahrt geplant.",
