    "Title": "Wo ist Annel 56 Reimer? 50-j",
    "Date": "1900-01-01",
    "Summary": "Bodenwerder (dy). Ich habe die Berichte iiber die vermisste alte Dame verfolgt und wollte erne helfen“, sagt Harald Hein. it seinem ‘Tragschrauber war der 50-Jahrige aus Bodenwerder am Himmelfahrtstag iiber der Weser im Einsatz, um nach An- neliese Reimer zu suchen. Die- sen privaten Flug hat er im Vor- Mit seinem gelben Tragschrauber will Harald Hein auch am heutigen Sonnabend noch einmal di feld der hiesigen Polizeidienst- stelle mitgeteilt. Trotz intensivster Suche von Polizei, DLRG, Johanniter-Un- fallhilfe, dem Einsatz von Hub- schraubern und Spiirhunden, ist die 84-Jahrige immer noch nicht gefunden. Bereits seit Donners- tag, 19. Mai, wird Anneliese Reimer — sie hat an dem Tag um die Wiesen von Polle bis nach Bodenwerder abfliegen. 20 Uhr: das Seniorenheim in Polle verlassen — vermisst. Polizeihauptkommissar Dirk Hartung und sein Kollege Poli- zeioberkommissar Dirk Volk- mann waren am Himmelfahrts- tag ebenfalls im Einsatz, suchten Die beiden Beamten der serschutzpolizei Nienburg hat- e Weser und Foto: pr 20 Uhr die Weser von Polle bis Hameln abgefahren; hatten mit Fernglasern die Uferbéschung » unter die Lupe genommen, wa- ren an jedem im Wasser stehen- den Baum herangefahren und hatten unter jeden Gegenstand geschaut. Von Polle bis Boden- werder.ist Harald Hein mit sei- nem kleinen gelben Trag- schrauber iiber die Weser geflo- gen. Mit einer Geschwindigkeit von 100 bis 120 Stundenkilome- ter — und das sei relativ langsam, so der Hobbypilot. 150 Meter aber Grund oder ,manchmal auch niedriger sei er geflogen, super, es war total klare Sicht und in den Buhnen, in denen das Wasser nicht aufgewiihlt ist, konnte ich bis zum Grund schauen“, so der fliegende Gar- tengestalter aus Bodenwerder. Problematisch sei es allerdings gewesen, dass er alleine geflogen ist. ,Flugverkehr in dieser Hohe gibt es zwar nicht, aber auf Greifvégel muss ich doch sehr achten“. Viele Freizeitboote und Kanus waren an dem Feiertag auf der Weser unterwegs, und so musste sich der Pilot wahn- sinnig konzentrieren. ,,Sie sehen von hier oben wirklich jede erlautert Hein. ,,Das Wetter war . Plastiktiite, die sich, irgendwo verfangen hat“, erzahlt Harald Hein von seinem knapp einstiin- digen Einsatz tiber dem. Fluss. Die’ 84-Jahrige kann ‘sich doch eigentlich gar nicht so weit vom Heim ungesehen. entfernt ha- ben“, ist Hein iiberzeugt. Des- halb wird er heute noch einmal mit seinem gelben Flieger nicht nur die Weser abfliegen, son- dern auch in Polle tiber Felder fliegen. , Uber die Fahre wird sie nicht gegangen sein, denn dann hatte sich ganz sicher schon je- mand an die Vermisste erin- nert“, so der engagierte Helfer. Wenn er heute startet, dann hat er auf jeden Fall einen zweiten Mann an Bord. ~~ Polizeihauptkommissar Hart- mut Freyer, Leiter der Polizei- _ dienststelle in Bodenwerder, au- ert sich sehr lobend iiber das Engagement von Harald Hein. Dass Harald Hein seinen priva- ten Flieger kostenlos fiir uns éinsetzt, das ist super“, so Frey- et. Die Suche nach Anneliese Reimer liuft unterdessen weiter. Die Polizei bittet auch die Be- volkerung um Mithilfe. Unter 05531/9580 ist die Dienststelle in Holzminden und unter 05533/ 974950. die Dienststelle in Bo- denwerder erreichbar.",
