    "Date": "2019-10-09",
    "Summary": "Eine Abordnung der Deutsch-Japanischen Gesellschaft Bielefeld war ktrzlich wieder einmal in Reileifzen zu Gast. Anlasslich des 50-jahrigen Bestehens des Heimat- und Verkehrsvereins Reileifzen im Juni 2019 hatte die DJG Bielefeld als Prasent einen Gutschein ftir einen Kirschbaum Uberreicht. Die Pradsidentin der DJG Bielefeld, Gesa Neuert, sowie der Vizeprasident, Andreas Koch, hatten bei ihrem Besuch in Reileifzen den versproche- nen Kirschbaum im Gepdack. Hierbei handelte es sich um eine alte japanische Kirsch- sorte, die in Deutschland nicht so haufig vorkommt. Der zweite Vorsitzende des Heimat- und Verkehrsvereins Reileifzen, Thorben Grihn, nahm das Geschenk gerne entgegen und pflanzte den Baum gemeinsam mit Gesa Neuert und Andreas Koch an seinem Bestimmungsort ein. AnschlieBend erfolgte noch ein reger Austausch beim Kar- toffelbraten der Feuerwehr Reileifzen. Der Kirschbaum wurde gemeinsam an seinem Bestimmungsort in Reileifzen eingepflanzt.",
