    "Title": "Verschmutzungen in Bodenwerder und Reileifzen",
    "Date": "2022-05-22",
    "Summary": "Gleich zwei Mal mussten am Pfingstwochenende Einsatzkräfte der Feuerwehren zu Ölspuren ausrücken. Zunächst wurden die Einsatzkräfte der Ortsfeuerwehr Bodenwerder am Sonnabend, 22. Mai, gegen 16 Uhr in die Homburgstraße in Bodenwerders Altstadt gerufen. Hier war vermutlich Dieselkraftstoff aus einem Fahrzeug ausgelaufen und hatte die Fahrbahn verunreinigt. Mit Bindemittel wurde die Verunreinigung abgestreut und so die Ölverschmutzung aufgenommen, um eine Gefahr für andere Verkehrsteilnehmer und die Umwelt zu beseitigen. Nach rund 20 Minuten war hier der Einsatz für die insgesamt neun Feuerwehrkräfte beendet. Eine weitere Verunreinigung wurde durch eine Polizeistreife am Sonntagnachmittag gegen 14.40 Uhr auf der Kreisstraße K 59 zwischen Forst und Reileifzen festgestellt. Nach Angaben des Ortsbrandmeisters aus Reileifzen, Marco Eikhoff, waren hier 24 Einsatzkräfte mit der Beseitigung der Ölspur beschäftigt. Zum Einsatz kam neben Bindemittel auch ein flüssiger Ölkiller, um die rund 150 Meter lange Verunreinigung zu beseitigen. Gegen 15.20 Uhr konnte auch hier der Einsatz beendet werden und die Feuerwehren wieder einrücken.",
    "Document": "./docs/Xerox Scan_17102023151522.PDF",
    "Thumbnail": "./thumbs/Xerox Scan_17102023151522_thumb.jpg"
