    "Title": "Diese Strae bleibt noch fiir Jahre gesperrt",
    "Date": "2021-07-08",
    "Summary": "2019, im August war das, waren die damalige Landratin Angela Schirzeberg und die Vertreter der Landesforsten noch zuversichtlich. Gerade hatten sie die KreisstraBe 32 zwischen Forst und der Poller Fahre sperren mtissen. Oberhalb der StraBe, im Hang der Heinse- ner Klippen drohten abge- storbene und absterbende Buchen auf die Fahrbahn zu fallen. Im Winter, so-der Plan, sollten die toten und kranken Buchen dort aus dem Fels ge- nommen werden, von einem alpin-erfahrenen Team. Zwei Jahre spater hat sich der Plan zerschlagen, weil die Hein- sener Klippen besonders geschitzt sind. Die erniichtern- de Auskunft heute: Die StraBe bleibt so lange dicht, bis die Natur selbst die Aufgabe erle- digt hat- durch natiirlichen Zerfall.",
