    "Title": "Lost Places",
    "Date": "2019-10-17",
    "Summary": "Die K 32 zwischen Forst und Holzminden musste 2019 gesperrt werden, weil am Hang abgestorbene Buchen sterben. Die Straße sollte kurzfristig repariert werden, aber jetzt bleibt sie gesperrt. Die abgestorbenen Bäume sind immer noch ein Problem und stellen eine Gefahr für Autofahrer dar. Radfahrer dürfen den zuvor gesperrten Radweg weiterhin nutzen. Die Heinsener Klippen, zu denen die abgestorbenen Buchen gehören, sind als FFH-Gebiet geschützt, daher ist es schwierig, die Bäume zu entfernen. Die Straße wird jedoch weiterhin gepflegt und instand gehalten.",
