    "Title": "Traktor-Gespann rutscht bei Reileifzen Abhang hinunter",
    "Date": "2022-09-26",
    "Summary": "Am Sonnabendabend befuhr gegen 18.30 Uhr ein Fahrer mit seinem landwirtschaftlichen Gespann die KreisstraBe 59 von Bevern-Forst kommend in Richtung Reileifzen. Der Fahrer kam alleinbeteiligt und aus bislang ungeklarter Ursache ins Rutschen, fuhr über die Leitplanke und stürzte anschließend nach rechts in den angrenzenden Abgrund. Zum Glück blieb der Fahrzeugführer unverletzt. Die Bergung der Fahrzeuge wird erst am Montag durch ein Spezialunternehmen erfolgen. Der entstandene Sachschaden wird auf rund 11.000 Euro veranschlagt. Es wird um Beachtung und Verständnis gebeten.",
